#include <iostream>
#include <cstring>
#include <string>
#include <string_view>

int main() {
    // --- 1. Sửa lỗi mảng chuỗi C-style ---
    char legacy_buf[16];
    std::strncpy(legacy_buf, "hello", 5);
    legacy_buf[5] = '\0'; // Bắt buộc phải có null-terminator

    const char* str1 = "test";
    const char* str2 = "test";
    bool legacy_equal = (std::strcmp(str1, str2) == 0); // So sánh đúng trong C

    // --- 2. Tiếp cận hiện đại với C++17 ---
    std::string modern_str = "hello";
    std::string_view sv = "Welcome Home";

    // So sánh trực quan và an toàn
    bool modern_equal = (modern_str == "hello");

    std::cout << "Legacy buffer: " << legacy_buf << "\n";
    std::cout << "Legacy equal check: " << (legacy_equal ? "true" : "false") << "\n";
    std::cout << "Modern string: " << modern_str << "\n";
    std::cout << "Modern view prefix: " << sv.substr(0, 7) << "\n";
    std::cout << "Modern equal check: " << (modern_equal ? "true" : "false") << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <string_view>

void tokenize_and_reverse(std::string_view text, std::string_view delims) {
    std::string words[10];
    size_t count = 0;
    size_t start = 0;

    while (start < text.size() && count < 10) {
        size_t first = text.find_first_not_of(delims, start);
        if (first == std::string_view::npos) break;
        size_t end = text.find_first_of(delims, first);
        if (end == std::string_view::npos) {
            words[count++] = std::string(text.substr(first));
            break;
        }
        words[count++] = std::string(text.substr(first, end - first));
        start = end + 1;
    }

    // In danh sách từ theo thứ tự đảo ngược (Tương ứng ví dụ cùng chủ đề)
    for (size_t i = count; i > 0; --i) {
        std::cout << words[i - 1] << (i > 1 ? " " : "\n");
    }
}

int main() {
    std::string_view sentence = "C++17 simplifies string processing greatly";
    std::cout << "Original: " << sentence << "\n";
    std::cout << "Reversed: ";
    tokenize_and_reverse(sentence, " ");
    return 0;
}

